'use strict';
let mapSearchPoint=null;
const modeBaseRender=render;render=function(){modeBaseRender();renderCoordinateOptions();$$('#trapTabs button').forEach(b=>b.classList.toggle('active',b.dataset.trap===activeTrap));const terrain=state.mapMode==='terrain';$('#placeTrapCoordinates').disabled=readonly;$$('[data-map-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mapMode===state.mapMode));$('#worldMapStatus').classList.toggle('hidden',!terrain);$('#mapModeDescription').textContent=terrain?'Starts with fixed terrain only. Search coordinates to place your traps.':'Starts with two traps. Fixed terrain is turned off.';$('#mapBadge').textContent=(terrain?'Terrain':'Plain')+' · '+(state.traps.length?(activeTrap==='all'?'Both traps':'BT '+activeTrap):'No bear traps placed');};
const modeBaseMap=renderMap;renderMap=function(){modeBaseMap();if(!mapSearchPoint)return;const o=Hive.worldOrigin(state),p=point(mapSearchPoint.x-o.x+.5,mapSearchPoint.y-o.y+.5),g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('data-coordinate-marker','true');g.setAttribute('pointer-events','none');g.innerHTML=`<circle cx="${p.x}" cy="${p.y}" r="13" fill="none" stroke="#a9482e" stroke-width="3"/><path d="M${p.x-20} ${p.y}h40 M${p.x} ${p.y-20}v40" stroke="#a9482e" stroke-width="2"/><text x="${p.x+17}" y="${p.y-15}" font-size="12" fill="#8c3322">X:${mapSearchPoint.x} Y:${mapSearchPoint.y}</text>`;$('#mapSvg').appendChild(g)};
function searchMap(x,y){if(![x,y].every(v=>Number.isInteger(v)&&v>=0&&v<=1199))throw Error('Enter whole coordinates from 0 to 1199.');mapSearchPoint={x,y};activeTrap='all';$$('#trapTabs button').forEach(b=>b.classList.toggle('active',b.dataset.trap==='all'));const o=Hive.worldOrigin(state),p=projected(x-o.x+.5,y-o.y+.5),box=$('#mapViewport').getBoundingClientRect();camera.k=Math.max(15,Math.min(camera.k,25));camera.x=box.width/2-p.x*camera.k;camera.y=box.height/2-p.y*camera.k;$('#coordinateResult').textContent=`X:${x} Y:${y} · Search marker only`;render();$('#mapViewport').scrollIntoView({block:'nearest',behavior:'smooth'})}
$('#coordinateForm').onsubmit=e=>{e.preventDefault();try{searchMap(+$('#mapSearchX').value,+$('#mapSearchY').value)}catch(e){toast(e.message)}};
function renderCoordinateOptions(){const kind=$('#coordinateTrap').value,selected=$('#coordinateMember').value;$('#coordinateMemberLabel').classList.toggle('hidden',kind!=='city');$('#coordinateGroupLabel').classList.toggle('hidden',kind!=='slot');$('#coordinateMember').innerHTML='<option value="">Choose a player…</option>'+state.members.filter(m=>[1,2].includes(m.trap)).map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''} ${m.locked?'disabled':''}>${esc(m.name)} · BT${m.trap}${m.locked?' · locked':''}</option>`).join('');$('#placeTrapCoordinates').textContent=['1','2'].includes(kind)?'Place bear trap':'Preview placement';}
$('#coordinateTrap').onchange=()=>renderCoordinateOptions();
$('#placeTrapCoordinates').onclick=()=>{try{if(!$('#mapSearchX').value||!$('#mapSearchY').value)throw Error('Enter X and Y coordinates.');const kind=$('#coordinateTrap').value,x=+$('#mapSearchX').value,y=+$('#mapSearchY').value;if(['1','2'].includes(kind)){const id=+kind,result=Hive.placeBearTrap(state,id,x,y),apply=()=>{commit(()=>state=result.state);closeModal();searchMap(x,y);$('#coordinateResult').textContent=`Bear Trap ${id} placed at X:${x} Y:${y}. Undo is available.`};if(state.traps.some(t=>t.id===id)){openModal(`<h2>Move Bear Trap ${id}?</h2><p>Move it to X:${x} Y:${y}. Its city spaces move with it. ${result.displaced.length} conflicting unlocked cities return to the queue. Undo is available.</p><button class="primary" id="confirmTrapCoordinates">Move bear trap</button>`);$('#confirmTrapCoordinates').onclick=apply}else apply();return}const memberId=$('#coordinateMember').value,trapId=+$('#coordinateGroup').value,next=Hive.placeMapObject(state,kind,x,y,{memberId,trapId}),names={city:'player city',slot:'city space',flag:'banner',hq:'alliance HQ',terrain:'blocked terrain'},m=state.members.find(m=>m.id===memberId),name=kind==='city'?m.name:names[kind],size=kind==='hq'?3:['city','slot'].includes(kind)?2:1;searchMap(x,y);openModal(`<div class="eyebrow">PLACEMENT PREVIEW</div><h2>Place ${esc(name)}?</h2><p>X:${x} Y:${y} · ${size}×${size} footprint. ${kind==='city'?'Updates the city position and move instructions.':''} Undo is available.</p><button class="primary" id="confirmCoordinateObject">Place ${esc(name)}</button>`);$('#confirmCoordinateObject').onclick=()=>{commit(()=>state=next);closeModal();searchMap(x,y);$('#coordinateResult').textContent=`Placed ${name} at X:${x} Y:${y}. Undo is available.`}}catch(e){toast(e.message)}};
$$('[data-map-mode]').forEach(b=>b.onclick=()=>{if(readonly)return;if(b.dataset.mapMode===state.mapMode)return;const next=Hive.switchMapMode(state,b.dataset.mapMode);commit(()=>state=next);mapSearchPoint=null;selectedMember=null;selectedSlot=null;setTool('select');activeTrap='all';$$('#trapTabs button').forEach(t=>t.classList.toggle('active',t.dataset.trap==='all'));render();fit();toast((state.mapMode==='terrain'?'Terrain':'Plain')+' map opened. Each mode keeps its own layout. Undo is available.')});
$('#resetLayoutBtn').onclick=()=>{const terrain=state.mapMode==='terrain';openModal(`<div class="eyebrow">RESET ${terrain?'TERRAIN':'PLAIN'} MAP</div><h2>Reset this map?</h2><p>${terrain?'Remove all placed bear traps, cities, city spaces and editable objects. Only fixed world terrain remains.':'Remove cities, city spaces and editable objects. Keep BT1 and BT2 at their configured coordinates.'}</p><p>Roster, attendance and the other map stay saved. Undo is available.</p><button class="primary" id="applyFactoryReset">Reset ${terrain?'terrain':'plain'} map</button>`);$('#applyFactoryReset').onclick=()=>{commit(()=>state=Hive.factoryResetMap(state));closeModal();selectedMember=null;selectedSlot=null;mapSearchPoint=null;setTool('select');fit();toast('Map reset. Undo is available.')}};
render();
